import re

def to_min(s):
    ampm = s[-2:]
    h, m = map(int, s[:-2].split(':'))
    if ampm == 'PM' and h != 12:
        h += 12
    if ampm == 'AM' and h == 12:
        h = 0
    return h * 60 + m

def fmt(t):
    t %= 1440
    h = t // 60
    m = t % 60
    if h == 0:
        h12 = 12
        ap = 'AM'
    elif h < 12:
        h12 = h
        ap = 'AM'
    elif h == 12:
        h12 = 12
        ap = 'PM'
    else:
        h12 = h - 12
        ap = 'PM'
    return f"{h12}:{m:02d}{ap}"

def parse_dist(text):
    dist = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        m = re.match(r"(.+) to (.+): (\d+)\.$", line)
        if m:
            dist[(m.group(1), m.group(2))] = int(m.group(3))
    return dist

def travel(dist, a, b):
    if a == b:
        return 0
    return dist.get((a, b), 0)

def solve(start_loc, start_time, friends, dist_text):
    dist = parse_dist(dist_text)
    n = len(friends)
    INF = 10 ** 9
    size = 1 << n
    pop = [0] * size
    for mask in range(1, size):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    dp = [[INF] * n for _ in range(size)]
    pred = [[-1] * n for _ in range(size)]

    for i, (name, loc, s, e, d) in enumerate(friends):
        t = start_time + travel(dist, start_loc, loc)
        mt = max(t, s)
        if mt + d <= e:
            dp[1 << i][i] = mt + d
            pred[1 << i][i] = -2

    for mask in range(size):
        for i in range(n):
            cur = dp[mask][i]
            if cur == INF:
                continue
            loc_i = friends[i][1]
            for j in range(n):
                if mask & (1 << j):
                    continue
                _, loc, s, e, d = friends[j]
                t = cur + travel(dist, loc_i, loc)
                mt = max(t, s)
                if mt + d <= e:
                    newmask = mask | (1 << j)
                    newend = mt + d
                    if newend < dp[newmask][j]:
                        dp[newmask][j] = newend
                        pred[newmask][j] = i

    best_mask = 0
    best_i = -1
    best_end = INF
    for mask in range(size):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            if pop[mask] > pop[best_mask] or (pop[mask] == pop[best_mask] and dp[mask][i] < best_end):
                best_mask = mask
                best_i = i
                best_end = dp[mask][i]

    order = []
    if best_i != -1:
        mask = best_mask
        i = best_i
        while i != -2:
            order.append(i)
            p = pred[mask][i]
            if p == -2:
                i = -2
            else:
                mask ^= (1 << i)
                i = p
        order.reverse()

